import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight, Zap, Loader2 } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';
import { supabase } from './supabaseClient';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

// Fixed: Changed onClose type from void to () => void to resolve TimerHandler error and prop assignment issues
const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(async () => {
      const now = new Date();
      const today = now.toLocaleDateString('en-CA');
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      const currentTimeNum = now.getHours() * 100 + now.getMinutes();

      const hospitals = await storageService.getHospitals();

      // 1. Handle Automatic Pass Expiration (Catch today's clock-outs AND older stale passes)
      const allPasses = await storageService.getPasses();
      let hasPassChanges = false;
      const updatedPasses = allPasses.map(p => {
        if (p.entryStatus === 'not_entered') {
          // If pass is from a previous day, it's expired
          if (p.passDate < today) {
            hasPassChanges = true;
            return { ...p, entryStatus: 'expired' as const };
          }
          // If pass is from today, check the clock based on session
          if (p.passDate === today) {
            let shouldExpire = false;
            if (p.session === 'MORNING' && currentTimeNum >= 1300) shouldExpire = true;
            if (p.session === 'EVENING' && currentTimeNum >= 2000) shouldExpire = true;
            if (p.session === 'FULL_DAY' && currentTimeNum >= 2000) shouldExpire = true;
            if (shouldExpire) {
              hasPassChanges = true;
              return { ...p, entryStatus: 'expired' as const };
            }
          }
        }
        return p;
      });

      if (hasPassChanges) {
        await storageService.savePasses(updatedPasses);
      }

      // 2. Handle Automatic Lottery Triggering
      for (const hosp of hospitals) {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) continue;

        const sessions: SessionType[] = ['MORNING', 'EVENING', 'FULL_DAY'];
        for (const sess of sessions) {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = await lotteryService.runLottery(hosp.id, sess);
              if (result.success || result.message === "No applications found." || result.message.includes("already executed")) {
                console.log(`[AUTOMATION] Logged lottery status for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
              }
            }
          }
        }
      }
    }, 60000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = async (e?: React.FormEvent) => {
    e?.preventDefault();
    setIsLoggingIn(true);

    try {
      if (role === 'MR') {
        const { data, error } = await supabase
          .from('profiles')
          .select('*, mrs(*, pharma_companies(name))')
          .eq('mobile_number', mobile)
          .eq('password', password)
          .eq('role', 'MR')
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id, 
            fullName: data.full_name, 
            role: 'MR', 
            loginId: data.mobile_number,
            mobileNumber: data.mobile_number,
            companyName: (data.mrs as any)?.pharma_companies?.name || 'Pharma'
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Welcome back, ${u.fullName}!`);
        } else {
          showFeedback("Invalid MR credentials.", 'error');
        }
      } else {
        let dbRole: string = role;
        if (role === 'ADMIN') dbRole = 'HOSPITAL_ADMIN';
        if (role === 'COMPANY_ADMIN') dbRole = 'COMPANY';

        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('role', dbRole)
          .eq('password', password)
          .or(`mobile_number.eq.${mobile},full_name.eq.${mobile}`)
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id,
            role: role, 
            fullName: data.full_name, 
            hospitalId: data.hospital_id,
            mobileNumber: data.mobile_number,
            companyId: data.role === 'COMPANY' ? data.id : undefined 
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${data.full_name}`);
        } else {
          showFeedback(`Invalid ${role} credentials.`, 'error');
        }
      }
    } catch (err) {
      showFeedback("Authentication failed. Please check connection and try again.", 'error');
    } finally {
      setIsLoggingIn(false);
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Live Production Access</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'SUPER_ADMIN', '123456')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center col-span-2 hover:bg-slate-900 transition-all">
                     <Crown className="h-3 w-3 mb-1" /> Login as Root Authority (DB)
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Mobile Number' : 'Login ID / Identity'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "077xxxxxxx" : role === 'SUPER_ADMIN' ? "Identity Name" : "Login ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button 
                  type="submit" 
                  disabled={isLoggingIn}
                  className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-70"
                >
                  {isLoggingIn ? <Loader2 className="h-5 w-5 animate-spin" /> : <>Access Secure System <ArrowRight className="h-5 w-5" /></>}
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default group">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-slate-900 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/20 shadow-xl group-hover:border-indigo-400 transition-all">
                <Zap className="h-4 w-4 text-indigo-400" />
                <span className="text-sm font-black text-white tracking-tighter lowercase">dren</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-indigo-200 uppercase tracking-widest opacity-60">Professional Field Intelligence 3.2</p>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user!} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user?.role === 'SUPER_ADMIN' ? 'Root Authority Control' : user?.role === 'MR' ? 'MR Dashboard' : `${user?.fullName} Management`}
      >
        {user?.role === 'MR' && <MRDashboard user={user as any} />}
        {user?.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user?.role === 'ADMIN' && <AdminDashboard user={user as any} />}
        {user?.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user?.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap, Timer, AlertTriangle, Loader2
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  switch (session) {
    case 'MORNING':
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Morning Window Open', range: '08:00 - 11:45' };
      return { open: false, message: 'Closed: Morning Scan (08:00 - 11:45)', range: '08:00 - 11:45' };
    case 'EVENING':
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Evening Window Open', range: '13:00 - 20:00' };
      return { open: false, message: 'Closed: Evening Scan (13:00 - 20:00)', range: '13:00 - 20:00' };
    case 'FULL_DAY':
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Full Day Window Open', range: '08:00 - 22:30' };
      return { open: false, message: 'Closed: Full Day Scan (08:00 - 22:30)', range: '08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed', range: '--:--' };
  }
};

const getExpiryTimeLabel = (session: SessionType) => {
  if (session === 'MORNING') return '01:00 PM';
  return '08:00 PM';
};

const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => { videoRef.current?.play().catch(console.error); }, 150);
        }
      } catch (err) {
        setError("Camera access denied. Please allow permissions.");
      }
    }
    setupCamera();
    return () => { if (activeStream) activeStream.getTracks().forEach(track => track.stop()); };
  }, []);

  const handleSimulateAuto = async () => {
    const currentPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => p.mrId === mrId && p.passDate === today && p.entryStatus === 'not_entered');
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);
    if (validPass) {
      onScan(`MEDPASS-GATE-${validPass.hospitalId}`);
    } else {
      onScan(""); 
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"><X className="h-6 w-6" /></button>
        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center"><AlertCircle className="h-12 w-12 text-red-500 mb-4" /><p className="text-white font-bold">{error}</p></div>
          ) : (
            <>
              <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>
        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center"><Smartphone className="h-6 w-6 text-indigo-400" /><h3 className="text-xl font-black text-white">Align with Gate QR</h3></div>
          <button onClick={handleSimulateAuto} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl active:scale-95">SIMULATE GATE DETECTION <Zap className="h-4 w-4" /></button>
        </div>
      </div>
      <style>{` @keyframes scan { 0%, 100% { top: 0%; opacity: 0.5; } 50% { top: 100%; opacity: 1; } } `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);
  const [successApplication, setSuccessApplication] = useState<{hosp: string, sess: string} | null>(null);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = await storageService.getHospitals();
    const apprvs = await storageService.getApprovals();
    const allApps = await storageService.getApplications();
    const a = allApps.filter(ap => ap.mrId === user.id);
    const allPasses = await storageService.getPasses();
    const p = allPasses.filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = async (qrValueInput?: string) => {
    const latestPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    let qrValue = qrValueInput || prompt("Enter Unique Hospital Gate ID (e.g. MEDPASS-GATE-h1):");

    if (!qrValue?.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR format.", "error");
      return;
    }

    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const myPassesToday = latestPasses.filter(p => p.mrId === user.id && p.passDate === today && p.entryStatus === 'not_entered');
    const myEligiblePasses = myPassesToday.filter(p => p.hospitalId === hospitalIdFromQR);

    if (myEligiblePasses.length === 0) {
      const otherPasses = myPassesToday.length > 0;
      if (otherPasses) {
        showFeedback("Wrong Gate: This pass belongs to another hospital. Try with the relevant hospital gate.", "error");
      } else {
        showFeedback("No valid entry pass found for today at this hospital.", "error");
      }
      return;
    }

    const activePass = myEligiblePasses.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      const status = getScanStatus(myEligiblePasses[0].session);
      showFeedback(`Scan Failed: ${status.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      issuedPassId: activePass.id, 
      entryTime: new Date().toISOString(), 
      verifiedBy: 'Self-Gate-Scanner' 
    };

    await storageService.savePasses(updatedPasses);
    const currentLogs = await storageService.getLogs();
    await storageService.saveLogs([...currentLogs, log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    refreshData();
    showFeedback(`Access approved for ${activePass.session} session!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  // Cooldown Logic: Selected for same hospital/session in last 3 days
  const getSessionCooldown = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const threeDaysAgo = new Date();
    threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
    const threeDaysAgoStr = threeDaysAgo.toLocaleDateString('en-CA');
    const todayStr = today.toLocaleDateString('en-CA');

    return passes.find(p => 
      p.hospitalId === hospitalId && 
      p.session === session && 
      p.passDate >= threeDaysAgoStr &&
      p.passDate < todayStr
    );
  };

  const getTodayApplication = (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toLocaleDateString('en-CA');
    return apps.find(a => a.hospitalId === hospitalId && a.session === session && a.applicationDate === todayStr);
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    // 1. Check if already applied today
    if (getTodayApplication(hospitalId, session)) {
      showFeedback("You have already applied for this session today.", "error");
      return;
    }

    // 2. Check Cooldown
    const cooldown = getSessionCooldown(hospitalId, session);
    if (cooldown) {
      showFeedback(`Cooldown active: You were recently selected for this session on ${cooldown.passDate}.`, "error");
      return;
    }

    setLoading(true);
