import { storageService } from './storageService';
import { SessionType, IssuedPass, PassApplication } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';

export const lotteryService = {
  calculatePriority: async (mrId: string): Promise<number> => {
    let score = 0;
    const now = new Date();
    const allPasses = await storageService.getPasses();

    // Penalty for missed entries (expired passes)
    const missed = allPasses.filter(p => p.mrId === mrId && p.entryStatus === 'expired');
    score += missed.length * PRIORITY_WEIGHTS.MISSED_ENTRY;

    // Bonus for time since last successful entry
    const entered = allPasses.filter(p => p.mrId === mrId && p.entryStatus === 'entered');

    if (entered.length > 0) {
      const sorted = [...entered].sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());
      const last = new Date(sorted[0].passDate);
      const diffDays = Math.floor((now.getTime() - last.getTime()) / (1000 * 3600 * 24));

      if (diffDays >= 14) score += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diffDays >= 7) score += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;

      // Cooldown penalty
      if (diffDays <= 3) score += PRIORITY_WEIGHTS.PASS_IN_LAST_3_DAYS;
    } else {
      score += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
    }

    return score;
  },

  runLottery: async (hospitalId: string, session: SessionType): Promise<{ success: boolean; count: number; message: string }> => {
    const hospitals = await storageService.getHospitals();
    const hosp = hospitals.find(h => h.id === hospitalId);
    if (!hosp) return { success: false, count: 0, message: "Hospital not found" };

    const today = new Date().toISOString().split('T')[0];
    const allApps = await storageService.getApplications();
    const allPasses = await storageService.getPasses();

    const alreadyRun = allApps.some(a => 
      a.hospitalId === hospitalId && 
      a.applicationDate === today && 
      a.session === session && 
      (a.status === 'selected' || a.status === 'waitlisted')
    );

    if (alreadyRun) return { success: false, count: 0, message: "Lottery already executed for this session today." };

    let sessionApps = allApps.filter(a => 
      a.hospitalId === hospitalId && 
      a.applicationDate === today && 
      a.session === session && 
      a.status === 'applied'
    );

    // SERVER-SIDE REJECTION: Enforce Cooldown during lottery logic
    // Even if they applied (maybe before the pass from 2 days ago was issued/synced),
    // we filter them out of selection if they had a pass in the last 3 days for THIS session/hosp.
    const threeDaysAgo = new Date();
    threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
    const threeDaysAgoStr = threeDaysAgo.toLocaleDateString('en-CA');

    sessionApps = sessionApps.filter(app => {
      const recentPassForSameSlot = allPasses.find(p => 
        p.mrId === app.mrId && 
        p.hospitalId === hospitalId && 
        p.session === session &&
        p.passDate >= threeDaysAgoStr &&
        p.passDate < today
      );
      return !recentPassForSameSlot;
    });

    if (sessionApps.length === 0) return { success: false, count: 0, message: "No eligible applications found." };

    const scored = await Promise.all(sessionApps.map(async a => ({ 
      ...a, 
      priorityScore: await lotteryService.calculatePriority(a.mrId) 
    })));

    scored.sort((a, b) => b.priorityScore - a.priorityScore);

    const limit = hosp.passLimits?.[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    const newPasses: IssuedPass[] = selected.map((s, i) => ({
      id: crypto.randomUUID(),
      mrId: s.mrId,
      hospitalId: s.hospitalId,
      session,
      passDate: today,
      timeSlot: TIME_SLOTS[i % TIME_SLOTS.length],
      qrCode: `QR-${s.id}`,
      entryStatus: 'not_entered'
    }));

    const updatedApps = allApps.map(original => {
      const isSel = selected.find(x => x.id === original.id);
      if (isSel) return { ...original, status: 'selected' as const, priorityScore: isSel.priorityScore };

      const isWait = waitlisted.find(x => x.id === original.id);
      if (isWait) return { ...original, status: 'waitlisted' as const, priorityScore: isWait.priorityScore };

      return original;
    });

    await storageService.saveApplications(updatedApps);
    const existingPasses = await storageService.getPasses();
    await storageService.savePasses([...existingPasses, ...newPasses]);

    return { success: true, count: selected.length, message: `Successfully issued ${selected.length} passes.` };
  }
};

