                      let btnText = open ? 'APPLY NOW' : 'CLOSED';
                      let btnColor = open ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' : 'bg-slate-200 text-slate-400 grayscale cursor-not-allowed';

                      if (alreadyApplied) {
                        btnText = 'APPLIED';
                        btnColor = 'bg-green-50 border-2 border-green-200 text-green-700 hover:bg-green-100';
                      } else if (cooldown?.isActive) {
                        btnText = 'COOLDOWN';
                        btnColor = 'bg-amber-50 border-2 border-amber-200 text-amber-700 hover:bg-amber-100';
                      }

                      return (
                        <div key={sess} className="space-y-1">
                          <button 
                            disabled={(!open && !alreadyApplied && !cooldown?.isActive) || loading} 
                            onClick={() => handleApply(h.id, sess)} 
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all ${btnColor}`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1 font-black">
                              {alreadyApplied && <CheckCircle className="h-3 w-3" />}
                              {cooldown?.isActive && <Timer className="h-3 w-3" />}
                              {btnText}
                            </span>
                          </button>
                          <div className="px-2 flex justify-between items-center text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                            <span>Window:</span>
                            <span>{window?.start} - {window?.end}</span>
                          </div>
                          {cooldown?.isActive && (
                            <div className="px-2 pt-1 flex items-center gap-1">
                              <AlertCircle className="h-2.5 w-2.5 text-amber-500" />
                              <p className="text-[8px] font-bold text-amber-600 uppercase">Eligible to apply on: {cooldown.nextEligibleDateStr}</p>
                            </div>
                          )}
                          {alreadyApplied && (
                            <div className="px-2 pt-1 flex items-center gap-1">
                              <CheckCircle className="h-2.5 w-2.5 text-green-500" />
                              <p className="text-[8px] font-bold text-green-600 uppercase">Wait for lottery results</p>
