import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap, Timer, AlertTriangle, Loader2
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  switch (session) {
    case 'MORNING':
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Morning Window Open', range: '08:00 - 11:45' };
      return { open: false, message: 'Closed: Morning Scan (08:00 - 11:45)', range: '08:00 - 11:45' };
    case 'EVENING':
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Evening Window Open', range: '13:00 - 20:00' };
      return { open: false, message: 'Closed: Evening Scan (13:00 - 20:00)', range: '13:00 - 20:00' };
    case 'FULL_DAY':
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Full Day Window Open', range: '08:00 - 22:30' };
      return { open: false, message: 'Closed: Full Day Scan (08:00 - 22:30)', range: '08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed', range: '--:--' };
  }
};

const getExpiryTimeLabel = (session: SessionType) => {
  if (session === 'MORNING') return '01:00 PM';
  return '08:00 PM';
};

const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => { videoRef.current?.play().catch(console.error); }, 150);
        }
      } catch (err) {
        setError("Camera access denied. Please allow permissions.");
      }
    }
    setupCamera();
    return () => { if (activeStream) activeStream.getTracks().forEach(track => track.stop()); };
  }, []);

  const handleSimulateAuto = async () => {
    const currentPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => p.mrId === mrId && p.passDate === today && p.entryStatus === 'not_entered');
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);
    if (validPass) {
      onScan(`MEDPASS-GATE-${validPass.hospitalId}`);
    } else {
      onScan(""); 
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"><X className="h-6 w-6" /></button>
        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center"><AlertCircle className="h-12 w-12 text-red-500 mb-4" /><p className="text-white font-bold">{error}</p></div>
          ) : (
            <>
              <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>
        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center"><Smartphone className="h-6 w-6 text-indigo-400" /><h3 className="text-xl font-black text-white">Align with Gate QR</h3></div>
          <button onClick={handleSimulateAuto} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl active:scale-95">SIMULATE GATE DETECTION <Zap className="h-4 w-4" /></button>
        </div>
      </div>
      <style>{` @keyframes scan { 0%, 100% { top: 0%; opacity: 0.5; } 50% { top: 100%; opacity: 1; } } `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);
  const [successApplication, setSuccessApplication] = useState<{hosp: string, sess: string} | null>(null);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = await storageService.getHospitals();
    const apprvs = await storageService.getApprovals();
    const allApps = await storageService.getApplications();
    const a = allApps.filter(ap => ap.mrId === user.id);
    const allPasses = await storageService.getPasses();
    const p = allPasses.filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = async (qrValueInput?: string) => {
    const latestPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    let qrValue = qrValueInput || prompt("Enter Unique Hospital Gate ID (e.g. MEDPASS-GATE-h1):");

    if (!qrValue?.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR format.", "error");
      return;
    }

    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const myPassesToday = latestPasses.filter(p => p.mrId === user.id && p.passDate === today && p.entryStatus === 'not_entered');
    const myEligiblePasses = myPassesToday.filter(p => p.hospitalId === hospitalIdFromQR);

    if (myEligiblePasses.length === 0) {
      const otherPasses = myPassesToday.length > 0;
      if (otherPasses) {
        showFeedback("Wrong Gate: This pass belongs to another hospital. Try with the relevant hospital gate.", "error");
      } else {
        showFeedback("No valid entry pass found for today at this hospital.", "error");
      }
      return;
    }

    const activePass = myEligiblePasses.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      const status = getScanStatus(myEligiblePasses[0].session);
      showFeedback(`Scan Failed: ${status.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      issuedPassId: activePass.id, 
      entryTime: new Date().toISOString(), 
      verifiedBy: 'Self-Gate-Scanner' 
    };

    await storageService.savePasses(updatedPasses);
    const currentLogs = await storageService.getLogs();
    await storageService.saveLogs([...currentLogs, log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    refreshData();
    showFeedback(`Access approved for ${activePass.session} session!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  /**
   * Cooldown Logic: 3 days after getting a pass for a specific hospital & session.
   * If they got a pass on Monday, they are blocked Tue, Wed, Thu. Next eligible is Friday.
   * This includes passes issued for TODAY.
   */
  const getSessionCooldownInfo = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const todayStr = today.toLocaleDateString('en-CA');

    // Find latest pass for this specific hospital and session (including today)
    const relevantPasses = passes
      .filter(p => p.hospitalId === hospitalId && p.session === session && p.passDate <= todayStr)
      .sort((a, b) => b.passDate.localeCompare(a.passDate));

    if (relevantPasses.length === 0) return null;

    const lastPassDate = new Date(relevantPasses[0].passDate);
    const nextEligibleDate = new Date(lastPassDate);
    nextEligibleDate.setDate(lastPassDate.getDate() + 4); // Date when cooldown ends (4 days after)

    const nextEligibleDateStr = nextEligibleDate.toLocaleDateString('en-CA');

    // If today is before next eligible date, cooldown is active
    if (todayStr < nextEligibleDateStr) {
      return {
        isActive: true,
        lastPassDate: relevantPasses[0].passDate,
        nextEligibleDateStr: nextEligibleDateStr
      };
    }

    return null;
  };

  const getTodayApplication = (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toLocaleDateString('en-CA');
    // We only care about pending 'applied' status here for the "APPLIED" button state
    return apps.find(a => a.hospitalId === hospitalId && a.session === session && a.applicationDate === todayStr && a.status === 'applied');
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    // 1. Check Cooldown First (Stronger condition)
    const cooldown = getSessionCooldownInfo(hospitalId, session);
    if (cooldown?.isActive) {
      showFeedback(`Cooldown Active: You were recently selected for this session. Next eligible to apply: ${cooldown.nextEligibleDateStr}`, "error");
      return;
    }

    // 2. Check if already applied today (pending)
    if (getTodayApplication(hospitalId, session)) {
      showFeedback("You have already applied for this session today.", "error");
      return;
    }

    setLoading(true);
    const todayStr = new Date().toLocaleDateString('en-CA');
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9), 
      mrId: user.id, 
      hospitalId, 
      session,
      applicationDate: todayStr, 
      priorityScore: 0, 
      status: 'applied', 
      createdAt: new Date().toISOString()
    };

    const currentApps = await storageService.getApplications();
    await storageService.saveApplications([...currentApps, newApp]);

    const hName = hospitals.find(h => h.id === hospitalId)?.name || 'Hospital';

    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      setSuccessApplication({ hosp: hName, sess: session });
    }, 600);
  };

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {/* Success Modal */}
      {successApplication && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl p-10 max-w-sm w-full text-center animate-in zoom-in-95 duration-300 border border-slate-100">
            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <CheckCircle2 className="h-10 w-10 text-green-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">Application Received!</h3>
            <p className="text-slate-500 text-sm mt-2 font-medium leading-relaxed">
              Your request for <span className="text-indigo-600 font-bold">{successApplication.hosp}</span> ({successApplication.sess}) has been logged. 
              Results will be finalized at the hospital's scheduled lottery time.
            </p>
            <button 
              onClick={() => setSuccessApplication(null)}
              className="mt-8 w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg hover:bg-indigo-700 transition-all active:scale-95"
            >
              Continue
            </button>
          </div>
        </div>
      )}

      {/* 60s Approval Countdown Overlay */}
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><CheckCircle2 className="h-16 w-16 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter uppercase">Gate Open</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-[10px] mb-12">Validation Successful • Proceed Now</p>
            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">{countdown}</div>
              <p className="text-white/80 text-sm font-bold mt-4">Seconds to enter</p>
            </div>
            <button onClick={() => setValidatedPass(null)} className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase shadow-xl active:scale-95 transition-all">Dismiss</button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      {/* AI Insights */}
      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your priority ranking..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-500" /> Facility Booking</h3>
              <div className="bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Apply Period</p>
              </div>
