import { supabase } from '../supabaseClient';
import { Hospital, HospitalUser } from '../types';

export const HospitalService = {
  getHospitals: async (): Promise<Hospital[]> => {
    const { data, error } = await supabase.from('hospitals').select('*');
    if (error) throw error;
    return (data || []).map(h => ({
      id: h.id,
      name: h.name,
      address: h.address,
      email: h.email,
      mobileNumber: h.mobile_number,
      isActive: h.is_active,
      supportedSessions: h.supported_sessions,
      passLimits: h.pass_limits,
      sessionWindows: h.session_windows,
      entryWindows: h.entry_windows,
      autoLotteryEnabled: h.auto_lottery_enabled,
      autoLotteryTimes: h.auto_lottery_times
    }));
  },

  saveHospitals: async (hospitals: Hospital[]): Promise<Hospital[]> => {
    const results: Hospital[] = [];
    for (const h of hospitals) {
      // Ensure we have a valid UUID to avoid NOT NULL constraint violations
      const targetId = (h.id && h.id.length > 20) ? h.id : crypto.randomUUID();

      const { data, error } = await supabase.from('hospitals').upsert({
        id: targetId,
        name: h.name,
        address: h.address,
        email: h.email,
        mobile_number: h.mobileNumber,
        is_active: h.isActive,
        supported_sessions: h.supportedSessions,
        pass_limits: h.passLimits,
        session_windows: h.sessionWindows,
        entry_windows: h.entryWindows,
        auto_lottery_enabled: h.autoLotteryEnabled,
        auto_lottery_times: h.autoLotteryTimes
      }).select().single();

      if (error) {
        console.error("Error saving hospital:", error);
        throw error;
      }
      if (data) {
        results.push({
          id: data.id,
          name: data.name,
          address: data.address,
          email: data.email,
          mobileNumber: data.mobile_number,
          isActive: data.is_active,
          supportedSessions: data.supported_sessions,
          passLimits: data.pass_limits,
          sessionWindows: data.session_windows,
          entryWindows: data.entry_windows,
          autoLotteryEnabled: data.auto_lottery_enabled,
          autoLotteryTimes: data.auto_lottery_times
        });
      }
    }
    return results;
  },

  getHospitalUsers: async (): Promise<HospitalUser[]> => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .in('role', ['HOSPITAL_ADMIN', 'SECURITY']);
    if (error) throw error;
    return (data || []).map(u => ({
      id: u.id,
      hospitalId: u.hospital_id,
      mobileNumber: u.mobile_number,
      password: u.password,
      role: u.role === 'HOSPITAL_ADMIN' ? 'ADMIN' : u.role as any,
      fullName: u.full_name
    }));
  },

  saveHospitalUsers: async (users: HospitalUser[]): Promise<HospitalUser[]> => {
    const results: HospitalUser[] = [];
    for (const u of users) {
      // CRITICAL: Generate a UUID if missing to satisfy the NOT NULL constraint on the profiles table
      const targetId = (u.id && u.id.length > 20) ? u.id : crypto.randomUUID();

      const { data, error } = await supabase.from('profiles').upsert({
        id: targetId,
        hospital_id: u.hospitalId,
        mobile_number: u.mobileNumber,
        password: u.password,
        role: u.role === 'ADMIN' ? 'HOSPITAL_ADMIN' : u.role,
        full_name: u.fullName
      }).select().single();

      if (error) {
        console.error("Error saving hospital user:", error);
        throw error;
      }
      if (data) {
        results.push({
          id: data.id,
          hospitalId: data.hospital_id,
          mobileNumber: data.mobile_number,
          password: data.password,
          role: data.role === 'HOSPITAL_ADMIN' ? 'ADMIN' : data.role as any,
          fullName: data.full_name
        });
      }
    }
    return results;
  },
};

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);

  // History Filters
  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  // Company selection state
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = await storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(await storageService.getMRs()); 
    setCompanies(await storageService.getCompanies());
    const allApps = await storageService.getApplications();
    setApps(allApps); 
    setPasses(await storageService.getPasses());
    setLogs(await storageService.getLogs());
    setApprovals(await storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        entryWindows: currentHosp.entryWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      const summary = await getAdminBriefing(
        allApps, 
        await storageService.getPasses(),
        currentHosp?.name || 'Hospital'
      );
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = async (session: SessionType) => {
    const result = await lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
