// Updated getScanStatus to accept hospital entry windows configuration
const getScanStatus = (session: SessionType, windows?: Record<string, { start: string; end: string }>) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  const window = windows?.[session];
  if (!window) {
    // If not configured, we use slightly wider safe fallbacks but warn
    return { open: false, message: 'Scanning window not configured by hospital', range: '--:--' };
  }

  const startNum = parseInt(window.start.replace(':', ''));
  const endNum = parseInt(window.end.replace(':', ''));

  if (currentTime >= startNum && currentTime <= endNum) {
    return { open: true, message: `${session} Window Open`, range: `${window.start} - ${window.end}` };
  }

  if (currentTime < startNum) {
    return { open: false, message: `Access Denied: Scan Window Starts at ${window.start}`, range: `${window.start} - ${window.end}` };
  }

  return { open: false, message: `Access Denied: Scan Window Ended at ${window.end}`, range: `${window.start} - ${window.end}` };
};

