const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);
  const [successApplication, setSuccessApplication] = useState<{hosp: string, sess: string} | null>(null);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = await storageService.getHospitals();
    const apprvs = await storageService.getApprovals();
    const allApps = await storageService.getApplications();
    const a = allApps.filter(ap => ap.mrId === user.id);
    const allPasses = await storageService.getPasses();
    const p = allPasses.filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = async (qrValueInput?: string) => {
    const latestPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    let qrValue = qrValueInput || prompt("Enter Unique Hospital Gate ID (e.g. MEDPASS-GATE-h1):");

    if (!qrValue?.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR format.", "error");
      return;
    }

    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const myPassesToday = latestPasses.filter(p => p.mrId === user.id && p.passDate === today && p.entryStatus === 'not_entered');
    const myEligiblePasses = myPassesToday.filter(p => p.hospitalId === hospitalIdFromQR);

    if (myEligiblePasses.length === 0) {
      const otherPasses = myPassesToday.length > 0;
      if (otherPasses) {
        showFeedback("Wrong Gate: This pass belongs to another hospital. Try with the relevant hospital gate.", "error");
      } else {
        showFeedback("No valid entry pass found for today at this hospital.", "error");
      }
      return;
    }

    // Pass validation using configured entry windows
    const currentHospital = hospitals.find(h => h.id === hospitalIdFromQR);
    const activePass = myEligiblePasses.find(p => getScanStatus(p.session, currentHospital?.entryWindows).open);

    if (!activePass) {
      const status = getScanStatus(myEligiblePasses[0].session, currentHospital?.entryWindows);
      showFeedback(`Scan Failed: ${status.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      issuedPassId: activePass.id, 
      entryTime: new Date().toISOString(), 
      verifiedBy: 'Self-Gate-Scanner' 
    };

    await storageService.savePasses(updatedPasses);
    const currentLogs = await storageService.getLogs();
    await storageService.saveLogs([...currentLogs, log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    refreshData();
    showFeedback(`Access approved for ${activePass.session} session!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const getSessionCooldownInfo = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const todayStr = today.toLocaleDateString('en-CA');

    const relevantPasses = passes
      .filter(p => p.hospitalId === hospitalId && p.session === session && p.passDate <= todayStr)
      .sort((a, b) => b.passDate.localeCompare(a.passDate));

    if (relevantPasses.length === 0) return null;

    const lastPassDate = new Date(relevantPasses[0].passDate);
    const nextEligibleDate = new Date(lastPassDate);
    nextEligibleDate.setDate(lastPassDate.getDate() + 4); 

    const nextEligibleDateStr = nextEligibleDate.toLocaleDateString('en-CA');

    if (todayStr < nextEligibleDateStr) {
      return {
        isActive: true,
        lastPassDate: relevantPasses[0].passDate,
        nextEligibleDateStr: nextEligibleDateStr
      };
    }

    return null;
  };

  const getTodayApplication = (hospitalId: string, session: SessionType) => {
    const todayStr = new Date().toLocaleDateString('en-CA');
    return apps.find(a => a.hospitalId === hospitalId && a.session === session && a.applicationDate === todayStr && a.status === 'applied');
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const cooldown = getSessionCooldownInfo(hospitalId, session);
    if (cooldown?.isActive) {
      showFeedback(`Cooldown Active: You were recently selected for this session. Next eligible to apply: ${cooldown.nextEligibleDateStr}`, "error");
      return;
    }

    if (getTodayApplication(hospitalId, session)) {
      showFeedback("You have already applied for this session today.", "error");
      return;
    }

    setLoading(true);
    const todayStr = new Date().toLocaleDateString('en-CA');
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9), 
      mrId: user.id, 
      hospitalId, 
      session,
      applicationDate: todayStr, 
      priorityScore: 0, 
      status: 'applied', 
      createdAt: new Date().toISOString()
    };

    const currentApps = await storageService.getApplications();
    await storageService.saveApplications([...currentApps, newApp]);

    const hName = hospitals.find(h => h.id === hospitalId)?.name || 'Hospital';

    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      setSuccessApplication({ hosp: hName, sess: session });
    }, 600);
  };

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {/* Success Modal */}
      {successApplication && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl p-10 max-w-sm w-full text-center animate-in zoom-in-95 duration-300 border border-slate-100">
            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <CheckCircle2 className="h-10 w-10 text-green-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">Application Received!</h3>
            <p className="text-slate-500 text-sm mt-2 font-medium leading-relaxed">
              Your request for <span className="text-indigo-600 font-bold">{successApplication.hosp}</span> ({successApplication.sess}) has been logged. 
              Results will be finalized at the hospital's scheduled lottery time.
            </p>
            <button 
              onClick={() => setSuccessApplication(null)}
              className="mt-8 w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg hover:bg-indigo-700 transition-all active:scale-95"
            >
              Continue
            </button>
          </div>
        </div>
      )}

      {/* 60s Approval Countdown Overlay */}
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><CheckCircle2 className="h-16 w-16 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter uppercase">Gate Open</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-[10px] mb-12">Validation Successful • Proceed Now</p>
            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">{countdown}</div>
              <p className="text-white/80 text-sm font-bold mt-4">Seconds to enter</p>
            </div>
            <button onClick={() => setValidatedPass(null)} className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase shadow-xl active:scale-95 transition-all">Dismiss</button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      {/* AI Insights */}
      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your priority ranking..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-500" /> Facility Booking</h3>
              <div className="bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Apply Period</p>
              </div>
            </div>
            <div className="grid gap-6 sm:grid-cols-2">
              {hospitals.filter(h => approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')).map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-all group">
                  <p className="font-bold text-slate-800 text-lg mb-4 group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      const alreadyApplied = getTodayApplication(h.id, sess);
                      const cooldown = getSessionCooldownInfo(h.id, sess);

                      let btnText = open ? 'APPLY NOW' : 'CLOSED';
                      let btnColor = open ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' : 'bg-slate-200 text-slate-400 grayscale cursor-not-allowed';

                      if (cooldown?.isActive) {
                        btnText = 'COOLDOWN';
                        btnColor = 'bg-amber-50 border-2 border-amber-200 text-amber-700 hover:bg-amber-100';
                      } else if (alreadyApplied) {
                        btnText = 'APPLIED';
                        btnColor = 'bg-green-50 border-2 border-green-200 text-green-700 hover:bg-green-100';
                      }

                      return (
                        <div key={sess} className="space-y-1">
                          <button 
                            disabled={(!open && !alreadyApplied && !cooldown?.isActive) || loading} 
                            onClick={() => handleApply(h.id, sess)} 
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all ${btnColor}`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1 font-black">
                              {alreadyApplied && !cooldown?.isActive && <CheckCircle className="h-3 w-3" />}
                              {cooldown?.isActive && <Timer className="h-3 w-3" />}
                              {btnText}
                            </span>
                          </button>
                          <div className="px-2 flex justify-between items-center text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                            <span>Window:</span>
                            <span>{window?.start} - {window?.end}</span>
                          </div>
                          {cooldown?.isActive && (
                            <div className="px-2 pt-1 flex items-center gap-1">
                              <AlertCircle className="h-2.5 w-2.5 text-amber-500" />
                              <p className="text-[8px] font-bold text-amber-600 uppercase">Eligible to apply on: {cooldown.nextEligibleDateStr}</p>
                            </div>
                          )}
                          {alreadyApplied && !cooldown?.isActive && (
                            <div className="px-2 pt-1 flex items-center gap-1">
                              <CheckCircle className="h-2.5 w-2.5 text-green-500" />
                              <p className="text-[8px] font-bold text-green-600 uppercase">Wait for lottery results</p>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="space-y-6">
            {/* Ready to Enter (Not Entered) */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Passes Today</h3>
                {activePassesToday.some(p => {
                  const hosp = hospitals.find(h => h.id === p.hospitalId);
                  return getScanStatus(p.session, hosp?.entryWindows).open;
                }) && (
                  <button onClick={() => setIsScanning(true)} className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-md active:scale-95 animate-bounce"><Camera className="h-3.5 w-3.5" /> Scan Gate QR</button>
                )}
              </div>
              <div className="space-y-4">
                {activePassesToday.map(p => {
                  const hosp = hospitals.find(h => h.id === p.hospitalId);
                  const status = getScanStatus(p.session, hosp?.entryWindows);
                  return (
                    <div key={p.id} className={`p-4 border-2 rounded-2xl transition-all ${status.open ? 'bg-indigo-50 border-indigo-100 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                      <div className="flex justify-between items-center mb-2">
                        <div className="flex items-center gap-1.5">
                           {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                           <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                        </div>
                        {status.open ? (
                          <span className="text-[9px] font-black text-indigo-600 bg-white px-2 py-0.5 rounded shadow-xs uppercase">Open</span>
                        ) : (
                          <span className="text-[9px] font-black text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs uppercase">Closed</span>
                        )}
                      </div>
                      <p className="font-bold text-slate-800 text-sm mb-3 leading-tight">{hosp?.name}</p>

                      <div className="space-y-2 mb-4">
                        <div className="flex justify-between items-center text-[9px] font-black uppercase text-slate-400 tracking-tighter bg-white/50 p-1.5 rounded-lg border border-slate-100">
                          <span>Scanning Window</span>
                          <span className="text-indigo-600 font-black">{status.range}</span>
                        </div>
                        <div className="flex justify-between items-center text-[9px] font-black uppercase text-slate-400 tracking-tighter bg-white/50 p-1.5 rounded-lg border border-slate-100">
                          <span>Expiry Time</span>
                          <span className="text-red-500 font-black">{getExpiryTimeLabel(p.session)}</span>
                        </div>
                      </div>

                      {!status.open && (
                         <div className="flex items-center gap-2 mb-4 p-2 bg-amber-50 rounded-lg border border-amber-100">
                            <AlertTriangle className="h-3 w-3 text-amber-500 shrink-0" />
                            <p className="text-[10px] font-bold text-amber-700">{status.message}</p>
                         </div>
                      )}

                      <div className="bg-white p-3 rounded-xl border border-indigo-100 flex justify-between items-center"><div className="text-[9px] font-black text-slate-400 uppercase">Slot</div><div className="text-xs font-black text-slate-700">{p.timeSlot}</div></div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        </div>
      )}

      {/* Directory and Profile tabs omitted for brevity, logic remains identical */}
      {isScanning && <QRScannerModal onClose={() => setIsScanning(false)} onScan={handleScanDetected} mrId={user.id} hospitals={hospitals} />}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink,
  QrCode
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);

  // History Filters
  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  // Company selection state
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = await storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(await storageService.getMRs()); 
    setCompanies(await storageService.getCompanies());
    const allApps = await storageService.getApplications();
    setApps(allApps); 
    setPasses(await storageService.getPasses());
    setLogs(await storageService.getLogs());
    setApprovals(await storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        entryWindows: currentHosp.entryWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      const summary = await getAdminBriefing(
        allApps, 
        await storageService.getPasses(),
        currentHosp?.name || 'Hospital'
      );
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = async (session: SessionType) => {
    const result = await lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = async () => {
    if (!editingHospital) return;
    const allHospitals = await storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    await storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System settings saved successfully.", "success");
  };

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const currentFieldData = (prev[field] as any) || {};
      return { ...prev, [field]: { ...currentFieldData, [sess]: value } };
    });
  };

  const toggleSupportedSession = (sess: SessionType) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const isSupported = prev.supportedSessions.includes(sess);
      const newSupported = isSupported 
        ? prev.supportedSessions.filter(s => s !== sess)
        : [...prev.supportedSessions, sess];

      const newAutoEnabled = { ...(prev.autoLotteryEnabled || {}) };
      if (isSupported) newAutoEnabled[sess] = false;

      return { ...prev, supportedSessions: newSupported, autoLotteryEnabled: newAutoEnabled };
    });
  };

  const handleUpdateApproval = async (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = await storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    await storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return (
    <div className="flex items-center justify-center p-20 text-slate-400 font-bold">
      Loading Facility Configuration...
    </div>
  );

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');

  const approvedMRs = mrs.filter(mr => 
    approvals.some(a => a.mrId === mr.id && a.hospitalId === user.hospitalId && a.status === 'approved')
  );

  const approvedCompanies = companies.filter(c => 
    approvedMRs.some(mr => mr.companyName === c.name)
  );

  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Analyzing booking patterns and priority scoring..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Partners</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="space-y-6">
          <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
                <Clock className="h-5 w-5 text-indigo-500" /> Live Lottery Control
              </h3>
              <button 
                onClick={() => setShowHowItWorks(!showHowItWorks)} 
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-colors"
              >
                <HelpCircle className="h-4 w-4" /> How it Works
              </button>
            </div>

            {showHowItWorks && (
              <div className="mb-8 p-6 bg-slate-50 rounded-2xl border border-slate-200 animate-in slide-in-from-top-4 duration-300">
                <h4 className="font-black text-slate-800 uppercase tracking-widest text-xs mb-4 underline decoration-indigo-200 underline-offset-4">Fairness Algorithm Logic</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">1. ELIGIBILITY</p>
                      <p className="text-[11px] font-medium text-slate-600">MRs who haven't had a pass in 3 days are eligible for a new selection.</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">2. WEIGHTING</p>
                      <p className="text-[11px] font-medium text-slate-600">Priority score increases the longer an MR has waited (Max bonus at 14 days).</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">3. SELECTION</p>
